from auto_config.generator.enb.managed_objects.managed_object import ManagedObject


class BbmodParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        bbmod_type = self.enb_ent_config['bbmods'][self.mo_num].get('type', '')
        self.set_bbmodBoardConfigType(execution_config, bbmod_type)

        if execution_config['is_fsm5'] and execution_config['release'] >= 21.7:
            self.set_parameter('bbPoolSizeLte', 'extended')

        self.set_administrativeState(execution_config, bbmod_type)
        self.set_bbCardUsage(execution_config)
        self.set_parameter('prodCodePlanned', self.getProdCodePlanned())

        if self.enb_ent_config['bbmods'][self.mo_num].get('rp3_port_usage') == 'RF':
            self.set_struct_parameter('srioConnectionList', 'linkId', '4')
            self.set_struct_parameter('srioConnectionList', 'mode', 'RF')

    def set_bbmodBoardConfigType(self, execution_config, bbmod_type):
        if execution_config['release'] >= 22.12107:
            if bbmod_type in ('ABIO', 'ABIN', 'ABIP', 'ABIQ'):
                self.set_parameter('bbmodBoardConfigType', 'Auto')
            else:
                self.drop_parameter('bbmodBoardConfigType')

    def set_administrativeState(self, execution_config, bbmod_type):
        if bbmod_type == 'ABIL' or execution_config['release'] >= 21:
            self.set_parameter('administrativeState', 'Unlocked')
        else:
            self.drop_parameter('administrativeState')

    def set_bbCardUsage(self, execution_config):
        bbCardUsage = self.get_bbCardUsage(execution_config)
        if bbCardUsage is not None:
            self.set_parameter('bbCardUsage', bbCardUsage)
        else:
            self.drop_parameter('bbCardUsage')

    def get_bbCardUsage(self, execution_config):
        if self.enb_ent_config['bbmods'][self.mo_num].get('bb_card_usage'):
            return self.enb_ent_config['bbmods'][self.mo_num]['bb_card_usage']
        elif execution_config['is_fsm5']:
            return '2'
        else:
            return None

    def getProdCodePlanned(self):
        return self.enb_ent_config['bbmods'][self.mo_num].get('prod_code_planned', '473096A.X31')
